<script setup>
import { computed, ref } from 'vue';
import { useAppStore } from '../../stores/appStore';
import { useLessonsStore } from '../../stores/lessonsStore';
import LessonFormModal from '../modals/LessonFormModal.vue';
import CardFormModal from '../modals/CardFormModal.vue';
import ConfirmModal from '../modals/ConfirmModal.vue';
const app = useAppStore(), store = useLessonsStore();
const lesson = computed(() => store.getLessonById(app.currentLessonId.value));
const preview = ref(false), editing = ref(false), cardIndex = ref(null), deleteIndex = ref(null), dragged = ref(null);
const canEdit = computed(() => app.isTeacher.value && !preview.value);
async function saveCard(card) { const cards = lesson.value.cards.map(c => ({...c})); if(cardIndex.value < 0) cards.push(card); else cards[cardIndex.value] = card; return store.updateLessonCards(lesson.value.id,cards); }
async function move(from,to) { if(store.isSaving.value || to<0 || to>=lesson.value.cards.length || from===null) return; const cards=[...lesson.value.cards]; const [c]=cards.splice(from,1); cards.splice(to,0,c); await store.updateLessonCards(lesson.value.id,cards); }
function call() { app.setCallContext({tab:'lessons',lessonId:lesson.value.id}); app.setTab('calls'); }
</script>
<template><section v-if="lesson"><button class="btn btn-ghost" @click="app.lessonsScreen.value='list'">← К урокам</button><div class="panel"><div class="section-row"><div><h1 class="screen-title">{{ lesson.title }}</h1><p class="screen-subtitle">{{ store.formatDate(lesson.createdAt) }} · {{ store.pluralizeCards(lesson.cards.length) }}</p></div><div class="actions"><button class="btn btn-accent" :disabled="!lesson.cards.length" @click="app.lessonsScreen.value='training'">Тренировка</button><button class="btn btn-secondary" @click="call">Видеозвонок</button><button v-if="app.isTeacher.value" class="btn btn-secondary" @click="preview=!preview">{{ preview ? 'Режим учителя' : 'Предпросмотр' }}</button><button v-if="canEdit" class="btn btn-secondary" @click="editing=true">Редактировать</button></div></div><p v-if="preview" class="preview-notice">Предпросмотр глазами ученика</p><details v-if="canEdit" open class="script-panel teacher-script"><summary>Скрипт для учителя</summary><div class="markdown-body" v-html="store.renderMarkdown(lesson.teacherScript) || '<p>План занятия пока не заполнен.</p>'" /></details><details open class="script-panel"><summary>Скрипт урока</summary><div class="markdown-body" v-html="store.renderMarkdown(lesson.studentScript) || '<p>Переходите к карточкам и тренировке.</p>'" /></details></div><div class="section-row"><h2>Флеш-карточки</h2><button v-if="canEdit" class="btn btn-primary" @click="cardIndex=-1">+ Добавить карточку</button></div><div class="cards-grid"><article v-for="(card,i) in lesson.cards" :key="i" class="flashcard-item" :draggable="canEdit && !store.isSaving.value" @dragstart="dragged=i" @dragend="dragged=null" @dragover.prevent @drop.prevent="canEdit && move(dragged,i)"><img :key="card.imageUrl" :src="card.imageUrl" :alt="card.text" class="flashcard-image" loading="lazy" @error="$event.target.src=store.FALLBACK_IMAGE_URI" /><div class="flashcard-body"><h3>{{ card.text }}</h3><p>{{ card.translation }}</p></div><div v-if="canEdit" class="flashcard-toolbar"><button class="icon-btn" :disabled="i===0 || store.isSaving.value" aria-label="Выше" @click="move(i,i-1)">↑</button><button class="icon-btn" :disabled="i===lesson.cards.length-1 || store.isSaving.value" aria-label="Ниже" @click="move(i,i+1)">↓</button><button class="icon-btn" :disabled="store.isSaving.value" aria-label="Изменить" @click="cardIndex=i">✎</button><button class="icon-btn danger" :disabled="store.isSaving.value" aria-label="Удалить" @click="deleteIndex=i">✕</button></div></article></div><p v-if="!lesson.cards.length" class="empty-state">Карточек пока нет.</p><LessonFormModal v-if="editing" :lesson="lesson" @saved="editing=false" @close="editing=false" /><CardFormModal v-if="cardIndex !== null" :card="cardIndex >= 0 ? lesson.cards[cardIndex] : null" :action="saveCard" @close="cardIndex=null" /><ConfirmModal v-if="deleteIndex !== null" title="Удалить карточку?" :message="lesson.cards[deleteIndex]?.text" :action="() => store.updateLessonCards(lesson.id,lesson.cards.filter((_,i)=>i!==deleteIndex))" @close="deleteIndex=null" /></section><div v-else class="empty-state">Урок не найден.<button class="btn" @click="app.lessonsScreen.value='list'">К списку</button></div></template>
